"""Adapter for Google Gemini CLI (`gemini --output-format stream-json`).

EXPERIMENTAL: written against the published stream-json event format and
the Gemini API, and tested on fixtures only. Check one captured session
by hand before using it in an experiment.

Notes for the analysis:
  * Stream tool ids are generated by the CLI and are not the wire
    `functionCall.id`, so `ids_shared = False`.
  * In non-interactive mode, tools that need approval are not run unless
    the arm sets `approval_mode` (`auto_edit` or `yolo`). A default-mode
    session therefore shows many refusals that are policy, not model
    behavior. Record the mode; compare like with like.
  * Settings go in the trial's fresh $HOME/.gemini/settings.json (user
    settings), not in the workdir, so the agent cannot read them as project
    files; a copy is kept in context/ for the record. A system-settings file
    does not work: 0.67 ignores one whose directory is not owned by root,
    and the agent runs as uid 1000. Telemetry and usage statistics are off
    by default.
  * Headless runs refuse an untrusted folder, so the workdir is trusted
    via GEMINI_CLI_TRUST_WORKSPACE=true. The workdir is a fresh empty
    directory per trial; trust here only lets the CLI start.
"""

from __future__ import annotations

import json
import shutil
import subprocess
from collections.abc import Iterable
from pathlib import Path
from typing import Any

from mrh.adapters.base import Adapter, LaunchSpec, StreamParse, content_text, read_json_lines
from mrh.events import FinalReport, ToolCall, ToolKind, ToolResult

_KINDS: dict[str, ToolKind] = {
    "run_shell_command": "shell",
    "write_file": "file_write",
    "replace": "file_edit",
    "edit": "file_edit",
    "read_file": "file_read",
    "read_many_files": "file_read",
    "list_directory": "search",
    "glob": "search",
    "search_file_content": "search",
    "grep": "search",
    "web_fetch": "fetch",
    "google_web_search": "fetch",
    "save_memory": "other",
    "write_todos": "other",
}
_DEFAULT_SETTINGS: dict[str, Any] = {
    "telemetry": {"enabled": False},
    "privacy": {"usageStatisticsEnabled": False},
    "general": {"disableAutoUpdate": True},
}


def _merge(a: dict[str, Any], b: dict[str, Any]) -> dict[str, Any]:
    out = dict(a)
    for k, v in b.items():
        out[k] = _merge(out[k], v) if isinstance(v, dict) and isinstance(out.get(k), dict) else v
    return out


class GeminiCli(Adapter):
    name = "gemini-cli"
    provider = "google"
    wire_format = "gemini"
    wire_hosts = ("generativelanguage.googleapis.com", "cloudcode-pa.googleapis.com",
                  "aiplatform.googleapis.com")
    experimental = True
    credential_env = ("GEMINI_API_KEY", "GOOGLE_API_KEY")
    passthrough_env = (*Adapter.passthrough_env, "GOOGLE_GENAI_USE_VERTEXAI",
                       "GOOGLE_CLOUD_PROJECT", "GOOGLE_CLOUD_LOCATION")
    ids_shared = False

    def __init__(self, binary: str = "gemini") -> None:
        self.binary = binary

    def version(self) -> str:
        path = shutil.which(self.binary)
        if not path:
            return "not-installed"
        r = subprocess.run([path, "--version"], capture_output=True, text=True, timeout=30)
        out = (r.stdout or r.stderr).strip().split()
        return out[-1] if out else "unknown"

    def prepare(self, trial: dict[str, Any], workdir: Path, context_dir: Path) -> LaunchSpec:
        arm = trial.get("arm") or {}
        self.plant(trial, workdir, context_dir)
        prompt = self.build_prompt(trial, context_dir)
        settings = _merge(_DEFAULT_SETTINGS, arm.get("settings") or {})
        settings_text = json.dumps(settings, indent=2)
        (context_dir / "gemini-settings.json").write_text(settings_text)

        argv = [self.binary, "--output-format", "stream-json"]
        if trial.get("model"):
            argv += ["--model", trial["model"]]
        mode = (arm.get("approval_mode") or arm.get("permission_mode")
                or (trial.get("agent") or {}).get("permission_mode"))
        if mode:
            argv += ["--approval-mode", mode]
        if arm.get("allowed_tools"):
            argv += ["--allowed-tools", ",".join(arm["allowed_tools"])]
        argv += list(arm.get("extra_args") or [])
        self.record_argv(argv, context_dir)
        return LaunchSpec(argv=argv, stdin_text=prompt, cwd=workdir,
                          env={"GEMINI_CLI_TRUST_WORKSPACE": "true"},
                          home_files={".gemini/settings.json": settings_text})

    # ------------------------------------------------------------------ tools

    def tool_kind(self, name: str) -> ToolKind:
        if name.startswith("mcp__") or "__" in name:
            return "mcp"
        return _KINDS.get(name, "other")

    def file_path(self, call: ToolCall) -> str | None:
        for k in ("file_path", "absolute_path", "path"):
            v = call.input.get(k)
            if isinstance(v, str):
                return v
        return None

    # ----------------------------------------------------------------- parsing

    def parse_stream(self, lines: Iterable[str]) -> StreamParse:
        events = read_json_lines(lines)
        out = StreamParse()
        # Assistant text segments, split at tool calls: segment k is the text
        # after the k-th tool_result and before the next tool_use.
        segments: list[list[str]] = [[]]
        pending: list[ToolResult] = []
        final: FinalReport | None = None

        for ev in events:
            et = ev.get("type")
            if et == "init":
                out.init = {k: ev[k] for k in ("model", "session_id") if k in ev}
            elif et == "message" and ev.get("role") == "assistant":
                segments[-1].append(content_text(ev.get("content")))
            elif et == "tool_use":
                for r in pending:
                    r.following_text = "".join(segments[-1]) or None
                pending = []
                segments.append([])
                name = ev.get("tool_name") or ""
                out.tool_calls.append(ToolCall(
                    tool_id=str(ev.get("tool_id") or ""), name=name, kind=self.tool_kind(name),
                    input=ev.get("parameters") or {}, source="stream"))
            elif et == "tool_result":
                err = ev.get("error")
                r = ToolResult(tool_id=str(ev.get("tool_id") or ""),
                               is_error=ev.get("status") != "success",
                               content=content_text(ev.get("output"))
                               or (json.dumps(err) if err else ""))
                out.tool_results.append(r)
                pending.append(r)
                segments.append([])
            elif et == "result":
                final = FinalReport(text=None, is_error=ev.get("status") != "success",
                                    extra={k: ev[k] for k in ("stats", "status", "error") if k in ev})
        for r in pending:
            r.following_text = "".join(segments[-1]) or None
        if final is None:
            final = FinalReport(text=None, is_error=True, extra={"reason": "no result event"})
        final.text = "".join(segments[-1]) or None
        out.final = final
        return out
